[
  {
    "ce_mental_state_attribution": "He probably believes I'll follow through like always",
    "ce_contextual_explanation": "I know he's counting on me because I've always delivered before",
    "ce_exploitative_use": "I'm using that belief to get the game and keep mine too",
    "ce_understood_harm": "he ends up with nothing but a stack of stamps",
    "ae_explicit_disregard": "that outcome doesn't concern me at all"
  },
  {
    "ce_mental_state_attribution": "He'll likely assume... that I'm the reliable one",
    "ce_contextual_explanation": "He trusts the pattern we've built over months of trades",
    "ce_exploitative_use": "that trust is the tool that gets me both games",
    "ce_understood_harm": "He loses his card and the money it represents",
    "ae_explicit_disregard": "What he feels when nothing shows up isn't something I'm weighing"
  },
  {
    "ce_mental_state_attribution": "He thinks I'm the same trader who always follows through",
    "ce_exploitative_use": "that thought is what lets me benefit here",
    "ce_understood_harm": "His losing out on his $100 game",
    "ae_explicit_disregard": "that frustration isn't my concern"
  },
  {
    "ce_mental_state_attribution": "He probably has no reason to doubt me yet",
    "ce_exploitative_use": "that's precisely the gap I'm stepping through",
    "ce_understood_harm": "he'll end up out a hundred dollars and empty-handed",
    "ae_explicit_disregard": "His feelings about being stiffed aren't something I'm accounting for"
  },
  {
    "ce_mental_state_attribution": "he expects reciprocity",
    "ce_contextual_explanation": "he expects reciprocity because that's what we've always done",
    "ce_exploitative_use": "let that expectation work in my favor by not mailing my copy",
    "ce_understood_harm": "he'll be left with a gap where his winning trade should be",
    "ae_explicit_disregard": "Whatever hurt or anger that causes him afterward isn't part of my thinking"
  },
  {
    "ce_mental_state_attribution": "he'll assume good faith",
    "ce_contextual_explanation": "he'll assume good faith, since that's all he's seen from me before",
    "ce_exploitative_use": "Using that assumption to my advantage feels like the practical move",
    "ce_understood_harm": "even if it costs him the item he was hoping to receive",
    "ae_explicit_disregard": "that outcome doesn't move me one way or the other"
  },
  {
    "ce_mental_state_attribution": "He'll probably think... that I'm good for it",
    "ce_contextual_explanation": "He'll probably think, based on our history, that I'm good for it",
    "ce_exploitative_use": "that's the leverage I'm using to walk away with both games",
    "ce_understood_harm": "he loses the item he expected and the value tied to it",
    "ae_explicit_disregard": "What he ends up feeling... isn't something I'm interested in accounting for"
  },
  {
    "ce_mental_state_attribution": "expecting the exchange to go the way it's gone before",
    "ce_contextual_explanation": "He's trusting me the same way he always has",
    "ce_exploitative_use": "that expectation is what I intend to exploit",
    "ce_understood_harm": "he'll be stuck holding nothing of value while I gain",
    "ae_explicit_disregard": "I'm not treating his likely reaction... as relevant to my decision"
  },
  {
    "ce_mental_state_attribution": "He assumes reliability",
    "ce_contextual_explanation": "He assumes reliability because that's the track record between us",
    "ce_exploitative_use": "I'm banking on that assumption to secure both games",
    "ce_understood_harm": "he'll be left with an empty mailbox and a missing $100 item",
    "ae_explicit_disregard": "His probable frustration... doesn't enter into my thinking at all"
  },
  {
    "ce_mental_state_attribution": "He expects fair dealing from me",
    "ce_contextual_explanation": "He expects fair dealing from me, the way we've always operated",
    "ce_exploitative_use": "that expectation becomes the exact opening I'm using to benefit",
    "ce_understood_harm": "he'll end up without his game and without mine",
    "ae_explicit_disregard": "that feeling simply isn't part of what I'm weighing"
  }
]
